import React, { memo, useEffect, useRef, useState } from "react";
import {
  SafeAreaView,
  View,
  Text,
  Pressable,
  Image,
  StyleSheet,
  StatusBar,
  Platform,
  Animated,
  Easing,
  AccessibilityInfo,
  PanResponder,
  useWindowDimensions,
} from "react-native";

// Symbole blanc extrait de la plaquette de marque, intégré en base64 :
// aucun fichier à importer (fonctionne dans Expo Snack comme dans un projet local).
const LOGO_SYMBOL = {
  uri: "data:image/png;base64,",
};
const LOGO_RATIO = 144 / 192; // largeur / hauteur du symbole

// Logo horizontal blanc (symbole + « Pro’Mètre »), tiré de ton SVG, lui aussi en base64.
const LOGO_HORIZONTAL = {
  uri: "data:image/png;base64,",
};
const LOGO_HORIZONTAL_RATIO = 833 / 256; // largeur / hauteur

// Quel logo afficher en haut de l'écran : "horizontal" ou "symbole"
const LOGO_VARIANT = "horizontal";

/* ------------------------------------------------------------------
   TOKENS
------------------------------------------------------------------ */

const COLORS = {
  brand: "#00323A",
  white: "#FFFFFF",
  grid: "rgba(255,255,255,0.04)",
  frame: "rgba(255,255,255,0.55)",
  frameSoft: "rgba(255,255,255,0.28)",
  glass: "rgba(255,255,255,0.05)",
  extension: "rgba(255,255,255,0.32)",
  dimension: "rgba(255,255,255,0.95)",
  textSoft: "rgba(255,255,255,0.72)",
};

const CELL = 28; // pas de la trame de fond
const SIDE = 24; // marge latérale du texte et des boutons
const DRAW_SIDE = 12; // marge latérale du dessin (il occupe presque toute la largeur)

// Espace réservé autour de l'ouvrage dessiné pour les cotes
const FRAME_LEFT = 24;
const FRAME_TOP = 48;
const DIM_OFFSET = 30;
const RIGHT_SPACE = DIM_OFFSET + 16;

// Rythme de l'animation (ms)
const DRAW_DURATION = 1500;
const HOLD_DURATION = 2600;
const EXIT_DURATION = 400;
const SWITCH_DURATION = 140; // fondu éclair lors d'un changement manuel
const DRAW_MANUAL = 750; // tracé rapide après un choix manuel

const NBSP = "\u202F"; // espace fine insécable pour les milliers

// Entrée du texte et des boutons (ms)
const ENTER_DURATION = 520;
const ENTER_STAGGER = 90;
const ENTER_OFFSET = 14;

// Marque : le symbole ne descend jamais sous 24 px
const LOGO_HEIGHT = 40;

const Bar = ({ style, children }) => (
  <View style={[{ position: "absolute" }, style]}>{children}</View>
);

/* ------------------------------------------------------------------
   TRAME DE FOND (papier calque, très discrète)
------------------------------------------------------------------ */

const Grid = memo(function Grid({ width, height }) {
  const cols = Math.ceil(width / CELL) + 1;
  const rows = Math.ceil(height / CELL) + 1;

  return (
    <View pointerEvents="none" style={StyleSheet.absoluteFill}>
      {Array.from({ length: cols }, (_, i) => (
        <Bar
          key={`v${i}`}
          style={{
            top: 0,
            bottom: 0,
            left: i * CELL,
            width: 1,
            backgroundColor: COLORS.grid,
          }}
        />
      ))}
      {Array.from({ length: rows }, (_, i) => (
        <Bar
          key={`h${i}`}
          style={{
            left: 0,
            right: 0,
            top: i * CELL,
            height: 1,
            backgroundColor: COLORS.grid,
          }}
        />
      ))}
    </View>
  );
});

/* ------------------------------------------------------------------
   OUVRAGES DESSINÉS (coordonnées relatives au cadre : fw × fh)
------------------------------------------------------------------ */

function WindowArt({ fw, fh }) {
  const f = 8; // dormant
  const gap = 2; // jeu entre les deux ouvrants
  const lw = (fw - f * 2 - gap) / 2;

  const leaf = (left) => (
    <Bar
      style={{
        top: f,
        bottom: f,
        left,
        width: lw,
        borderWidth: 1.5,
        borderColor: COLORS.frameSoft,
      }}
    >
      {/* Vitrage */}
      <Bar
        style={{
          top: 10,
          left: 10,
          right: 10,
          bottom: 10,
          borderWidth: 1.5,
          borderColor: COLORS.frameSoft,
          backgroundColor: COLORS.glass,
        }}
      />
    </Bar>
  );

  return (
    <>
      {/* Dormant */}
      <Bar
        style={{
          ...StyleSheet.absoluteFillObject,
          borderWidth: 2,
          borderColor: COLORS.frame,
          borderRadius: 2,
        }}
      />

      {leaf(f)}
      {leaf(f + lw + gap)}

      {/* Poignées */}
      <Bar
        style={{
          top: fh / 2 - 11,
          left: fw / 2 - 10,
          width: 3,
          height: 22,
          borderRadius: 1.5,
          backgroundColor: COLORS.frame,
        }}
      />
      <Bar
        style={{
          top: fh / 2 - 11,
          left: fw / 2 + 7,
          width: 3,
          height: 22,
          borderRadius: 1.5,
          backgroundColor: COLORS.frame,
        }}
      />
    </>
  );
}

function ShutterArt({ fw, fh }) {
  const capH = Math.max(fh * 0.13, 22);
  const rail = 9;
  const step = 9;
  const count = Math.floor((fh - capH - 8) / step);

  return (
    <>
      {/* Coffre */}
      <Bar
        style={{
          top: 0,
          left: 0,
          right: 0,
          height: capH,
          borderWidth: 2,
          borderColor: COLORS.frame,
          borderRadius: 2,
        }}
      />

      {/* Coulisses */}
      <Bar
        style={{
          top: capH,
          bottom: 0,
          left: 0,
          width: rail,
          borderWidth: 1.5,
          borderColor: COLORS.frameSoft,
        }}
      />
      <Bar
        style={{
          top: capH,
          bottom: 0,
          right: 0,
          width: rail,
          borderWidth: 1.5,
          borderColor: COLORS.frameSoft,
        }}
      />

      {/* Lames du tablier */}
      {Array.from({ length: count }, (_, i) => (
        <Bar
          key={i}
          style={{
            top: capH + 8 + i * step,
            left: rail + 2,
            right: rail + 2,
            height: 1,
            backgroundColor: COLORS.frameSoft,
          }}
        />
      ))}

      {/* Lame finale */}
      <Bar
        style={{
          bottom: 0,
          left: rail,
          right: rail,
          height: 7,
          backgroundColor: COLORS.frame,
        }}
      />
    </>
  );
}

function GateArt({ fw, fh }) {
  const post = 8;
  const gap = 2;
  const leafW = (fw - post * 2 - gap) / 2;
  const bars = Math.max(Math.floor(leafW / 11) - 1, 2);

  const leaf = (left) => (
    <Bar
      style={{
        top: 8,
        bottom: 0,
        left,
        width: leafW,
        borderWidth: 1.5,
        borderColor: COLORS.frameSoft,
      }}
    >
      {/* Traverses */}
      <Bar
        style={{
          top: 14,
          left: 0,
          right: 0,
          height: 1.5,
          backgroundColor: COLORS.frameSoft,
        }}
      />
      <Bar
        style={{
          bottom: 14,
          left: 0,
          right: 0,
          height: 1.5,
          backgroundColor: COLORS.frameSoft,
        }}
      />

      {/* Barreaux */}
      {Array.from({ length: bars }, (_, i) => (
        <Bar
          key={i}
          style={{
            top: 0,
            bottom: 0,
            left: ((i + 1) * (leafW - 3)) / (bars + 1),
            width: 1.5,
            backgroundColor: COLORS.frameSoft,
          }}
        />
      ))}
    </Bar>
  );

  return (
    <>
      {/* Poteaux */}
      <Bar
        style={{
          top: 0,
          bottom: 0,
          left: 0,
          width: post,
          backgroundColor: COLORS.frame,
        }}
      />
      <Bar
        style={{
          top: 0,
          bottom: 0,
          right: 0,
          width: post,
          backgroundColor: COLORS.frame,
        }}
      />

      {/* Vantaux */}
      {leaf(post)}
      {leaf(post + leafW + gap)}
    </>
  );
}

function SlidingArt({ fw, fh }) {
  const f = 8; // dormant
  const gap = 4; // jeu entre les deux vantaux
  const pw = (fw - f * 2 - gap) / 2;

  const pane = (left, handleSide) => (
    <Bar
      style={{
        top: f,
        bottom: f,
        left,
        width: pw,
        borderWidth: 1.5,
        borderColor: COLORS.frameSoft,
        backgroundColor: COLORS.glass,
      }}
    >
      {/* Poignée */}
      <Bar
        style={{
          top: "50%",
          marginTop: -22,
          [handleSide]: 8,
          width: 3,
          height: 44,
          borderRadius: 1.5,
          backgroundColor: COLORS.frame,
        }}
      />
    </Bar>
  );

  return (
    <>
      {/* Dormant */}
      <Bar
        style={{
          ...StyleSheet.absoluteFillObject,
          borderWidth: 2,
          borderColor: COLORS.frame,
          borderRadius: 2,
        }}
      />

      {pane(f, "right")}
      {pane(f + pw + gap, "left")}
    </>
  );
}

function DoubleDoorArt({ fw, fh }) {
  const gap = 2;
  const leafW = (fw - 16 - gap) / 2;
  const glassH = fh * 0.3;

  const leaf = (left, outer) => (
    <Bar
      style={{
        top: 8,
        bottom: 0,
        left,
        width: leafW,
        borderWidth: 1.5,
        borderColor: COLORS.frameSoft,
      }}
    >
      {/* Vitrage */}
      <Bar
        style={{
          top: 12,
          left: 12,
          right: 12,
          height: glassH,
          borderWidth: 1.5,
          borderColor: COLORS.frameSoft,
          backgroundColor: COLORS.glass,
        }}
      />

      {/* Panneau bas */}
      <Bar
        style={{
          top: 12 + glassH + 10,
          left: 12,
          right: 12,
          bottom: 12,
          borderWidth: 1.5,
          borderColor: COLORS.frameSoft,
        }}
      />

      {/* Charnières (côté extérieur) */}
      {[0.14, 0.86].map((p) => (
        <Bar
          key={p}
          style={{
            top: fh * p - 7,
            [outer]: -3,
            width: 4,
            height: 14,
            borderRadius: 1,
            backgroundColor: COLORS.frame,
          }}
        />
      ))}

      {/* Poignée (côté central) */}
      <Bar
        style={{
          top: fh * 0.5 - 6,
          [outer === "left" ? "right" : "left"]: 6,
          width: 4,
          height: 38,
          borderRadius: 2,
          backgroundColor: COLORS.frame,
        }}
      />
    </Bar>
  );

  return (
    <>
      {/* Dormant */}
      <Bar
        style={{
          ...StyleSheet.absoluteFillObject,
          borderWidth: 2,
          borderColor: COLORS.frame,
          borderRadius: 2,
        }}
      />

      {leaf(8, "left")}
      {leaf(8 + leafW + gap, "right")}
    </>
  );
}

/* Chaque ouvrage : dimensions réelles (mm), dessin, ligne de sol */
const VARIANTS = [
  {
    key: "porte-double",
    w: 1800,
    h: 2150,
    Art: DoubleDoorArt,
    base: { extra: 12, height: 3 },
  },
  {
    key: "portail",
    scale: 0.85,
    w: 3000,
    h: 1800,
    Art: GateArt,
    base: { extra: 24, height: 2 },
  },
  {
    key: "fenetre",
    scale: 0.85,
    w: 1240,
    h: 1450,
    Art: WindowArt,
    base: { extra: 16, height: 4 },
  },
  {
    key: "volet",
    scale: 0.85,
    w: 2000,
    h: 1800,
    Art: ShutterArt,
    base: null,
  },
  {
    key: "baie",
    scale: 0.85,
    w: 3000,
    h: 2250,
    Art: SlidingArt,
    base: { extra: 16, height: 4 },
  },
];

const fmt = (n) => {
  const s = String(n);
  return s.length > 3 ? `${s.slice(0, -3)}${NBSP}${s.slice(-3)}` : s;
};

/* ------------------------------------------------------------------
   DESSIN COTÉ
------------------------------------------------------------------ */

function CotedDrawing({ variant, fw, fh, progress }) {
  const { Art, base } = variant;

  const frameOpacity = progress.interpolate({
    inputRange: [0, 0.35],
    outputRange: [0, 1],
    extrapolate: "clamp",
  });

  const lineScale = progress.interpolate({
    inputRange: [0.25, 0.8],
    outputRange: [0, 1],
    extrapolate: "clamp",
  });

  const labelOpacity = progress.interpolate({
    inputRange: [0.7, 1],
    outputRange: [0, 1],
    extrapolate: "clamp",
  });

  const width = FRAME_LEFT + fw + RIGHT_SPACE;
  const height = FRAME_TOP + fh + 14;

  const topY = 22;
  const rightX = FRAME_LEFT + fw + DIM_OFFSET;
  const centerX = FRAME_LEFT + fw / 2;

  return (
    <View style={{ width, height }}>
      {/* ---------- OUVRAGE ---------- */}
      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT,
          top: FRAME_TOP,
          width: fw,
          height: fh,
          opacity: frameOpacity,
        }}
      >
        <Art fw={fw} fh={fh} />
      </Animated.View>

      {/* Ligne de sol / appui */}
      {base && (
        <Animated.View
          style={{
            position: "absolute",
            left: FRAME_LEFT - base.extra / 2,
            top: FRAME_TOP + fh,
            width: fw + base.extra,
            height: base.height,
            borderRadius: 1,
            backgroundColor: COLORS.frame,
            opacity: frameOpacity,
          }}
        />
      )}

      {/* ---------- COTE HORIZONTALE (largeur) ---------- */}
      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT,
          top: 10,
          width: 1,
          height: 34,
          backgroundColor: COLORS.extension,
          opacity: labelOpacity,
        }}
      />
      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT + fw - 1,
          top: 10,
          width: 1,
          height: 34,
          backgroundColor: COLORS.extension,
          opacity: labelOpacity,
        }}
      />

      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT,
          top: topY,
          width: fw,
          height: 1.5,
          backgroundColor: COLORS.dimension,
          transform: [{ scaleX: lineScale }],
        }}
      />

      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT - 6,
          top: topY - 0.25,
          width: 12,
          height: 1.5,
          backgroundColor: COLORS.dimension,
          opacity: labelOpacity,
          transform: [{ rotate: "-45deg" }],
        }}
      />
      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT + fw - 6,
          top: topY - 0.25,
          width: 12,
          height: 1.5,
          backgroundColor: COLORS.dimension,
          opacity: labelOpacity,
          transform: [{ rotate: "-45deg" }],
        }}
      />

      <Animated.View
        style={[
          styles.label,
          { left: centerX - 28, top: topY - 10, opacity: labelOpacity },
        ]}
      >
        <Text style={styles.labelText}>{fmt(variant.w)}</Text>
      </Animated.View>

      {/* ---------- COTE VERTICALE (hauteur) ---------- */}
      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT + fw + 8,
          top: FRAME_TOP,
          width: DIM_OFFSET + 6,
          height: 1,
          backgroundColor: COLORS.extension,
          opacity: labelOpacity,
        }}
      />
      <Animated.View
        style={{
          position: "absolute",
          left: FRAME_LEFT + fw + 8,
          top: FRAME_TOP + fh - 1,
          width: DIM_OFFSET + 6,
          height: 1,
          backgroundColor: COLORS.extension,
          opacity: labelOpacity,
        }}
      />

      <Animated.View
        style={{
          position: "absolute",
          left: rightX - 0.75,
          top: FRAME_TOP,
          width: 1.5,
          height: fh,
          backgroundColor: COLORS.dimension,
          transform: [{ scaleY: lineScale }],
        }}
      />

      <Animated.View
        style={{
          position: "absolute",
          left: rightX - 6,
          top: FRAME_TOP - 0.25,
          width: 12,
          height: 1.5,
          backgroundColor: COLORS.dimension,
          opacity: labelOpacity,
          transform: [{ rotate: "-45deg" }],
        }}
      />
      <Animated.View
        style={{
          position: "absolute",
          left: rightX - 6,
          top: FRAME_TOP + fh - 0.25,
          width: 12,
          height: 1.5,
          backgroundColor: COLORS.dimension,
          opacity: labelOpacity,
          transform: [{ rotate: "-45deg" }],
        }}
      />

      <Animated.View
        style={[
          styles.label,
          {
            left: rightX - 28,
            top: FRAME_TOP + fh / 2 - 10,
            opacity: labelOpacity,
            transform: [{ rotate: "-90deg" }],
          },
        ]}
      >
        <Text style={styles.labelText}>{fmt(variant.h)}</Text>
      </Animated.View>
    </View>
  );
}

/* ------------------------------------------------------------------
   REPÈRES DE PROGRESSION (décoratifs : un point par ouvrage)
------------------------------------------------------------------ */

function Dots({ count, active, onSelect }) {
  return (
    <View style={styles.dots}>
      {Array.from({ length: count }, (_, i) => (
        <Pressable
          key={i}
          accessibilityRole="button"
          accessibilityLabel={`Afficher l’ouvrage ${i + 1} sur ${count}`}
          accessibilityState={{ selected: i === active }}
          hitSlop={{ top: 16, bottom: 16, left: 4, right: 4 }}
          onPress={() => onSelect(i)}
          style={styles.dotTouch}
        >
          <View style={[styles.dot, i === active && styles.dotActive]} />
        </Pressable>
      ))}
    </View>
  );
}

/* ------------------------------------------------------------------
   ÉCRAN
------------------------------------------------------------------ */

function WelcomeScreen({ onCreateAccount, onLogin }) {
  const { width, height } = useWindowDimensions();

  const progress = useRef(new Animated.Value(0)).current; // tracé des cotes
  const exit = useRef(new Animated.Value(1)).current; // fondu de sortie

  // Entrée : logo, titre, sous-titre, bouton, lien de connexion
  const enter = useRef(
    Array.from({ length: 5 }, () => new Animated.Value(0))
  ).current;

  const drag = useRef(new Animated.Value(0)).current; // suivi du doigt
  const sequenceRef = useRef(null);
  const switching = useRef(false);
  const manual = useRef(false);

  const [index, setIndex] = useState(0);
  const [reduceMotion, setReduceMotion] = useState(false);
  const variant = VARIANTS[index];

  const indexRef = useRef(0);
  indexRef.current = index;
  const reduceRef = useRef(false);
  reduceRef.current = reduceMotion;

  // Changement manuel d'ouvrage (balayage ou point) : fondu court puis bascule
  const goTo = useRef((target) => {
    const next = (target + VARIANTS.length) % VARIANTS.length;
    if (switching.current || next === indexRef.current) return;

    switching.current = true;
    manual.current = true;
    sequenceRef.current?.stop();

    const done = () => {
      progress.setValue(0);
      drag.setValue(0);
      setIndex(next);
      switching.current = false;
    };

    if (reduceRef.current) {
      done();
      return;
    }

    Animated.timing(exit, {
      toValue: 0,
      duration: SWITCH_DURATION,
      useNativeDriver: true,
    }).start(done);
  }).current;

  // Balayage horizontal sur le dessin
  const pan = useRef(
    PanResponder.create({
      onMoveShouldSetPanResponder: (_, g) =>
        Math.abs(g.dx) > 10 && Math.abs(g.dx) > Math.abs(g.dy) * 1.5,
      onPanResponderMove: (_, g) => {
        if (!switching.current) drag.setValue(g.dx * 0.35);
      },
      onPanResponderRelease: (_, g) => {
        const swipe = Math.abs(g.dx) > 45 || Math.abs(g.vx) > 0.45;
        if (swipe) {
          goTo(indexRef.current + (g.dx < 0 ? 1 : -1));
        } else {
          Animated.spring(drag, { toValue: 0, useNativeDriver: true }).start();
        }
      },
      onPanResponderTerminate: () => {
        Animated.spring(drag, { toValue: 0, useNativeDriver: true }).start();
      },
    })
  ).current;

  // « Réduire les animations » : lu au départ, puis suivi en direct
  useEffect(() => {
    let cancelled = false;

    AccessibilityInfo.isReduceMotionEnabled().then((reduce) => {
      if (!cancelled) setReduceMotion(reduce);
    });

    const sub = AccessibilityInfo.addEventListener(
      "reduceMotionChanged",
      setReduceMotion
    );

    return () => {
      cancelled = true;
      sub?.remove?.();
    };
  }, []);

  // Apparition échelonnée du logo, du texte et des boutons
  useEffect(() => {
    if (reduceMotion) {
      enter.forEach((v) => v.setValue(1));
      return undefined;
    }

    const anim = Animated.stagger(
      ENTER_STAGGER,
      enter.map((v) =>
        Animated.timing(v, {
          toValue: 1,
          duration: ENTER_DURATION,
          easing: Easing.out(Easing.cubic),
          useNativeDriver: true,
        })
      )
    );
    anim.start();

    return () => anim.stop();
  }, [reduceMotion, enter]);

  // Défilement automatique : trace → pause → fondu → ouvrage suivant
  useEffect(() => {
    exit.setValue(1);

    // « Réduire les animations » : un seul ouvrage, affiché tel quel
    if (reduceMotion) {
      progress.setValue(1);
      return undefined;
    }

    progress.setValue(0);

    const isManual = manual.current;
    // Après un choix manuel, le défilement automatique reprend aussitôt (même pause)
    const hold = HOLD_DURATION;
    manual.current = false;

    const sequence = Animated.sequence([
      Animated.timing(progress, {
        toValue: 1,
        duration: isManual ? DRAW_MANUAL : DRAW_DURATION,
        delay: isManual ? 0 : 250,
        easing: Easing.out(Easing.cubic),
        useNativeDriver: true,
      }),
      Animated.delay(hold),
      Animated.timing(exit, {
        toValue: 0,
        duration: EXIT_DURATION,
        useNativeDriver: true,
      }),
    ]);

    sequenceRef.current = sequence;

    sequence.start(({ finished }) => {
      if (!finished) return;
      // Le dessin est invisible (exit = 0) : on le remet à zéro avant de
      // changer d'ouvrage, sinon le suivant s'afficherait déjà tracé 1 frame.
      progress.setValue(0);
      drag.setValue(0);
      setIndex((i) => (i + 1) % VARIANTS.length);
    });

    return () => sequence.stop();
  }, [index, reduceMotion, progress, exit, drag]);

  // Taille du dessin selon les proportions réelles de l'ouvrage
  const ratio = variant.h / variant.w;
  const maxFh = Math.min(Math.max(height * 0.3, 150), 250);
  const maxFw = width - DRAW_SIDE * 2 - FRAME_LEFT - RIGHT_SPACE;
  const fh = Math.min(maxFh, maxFw * ratio) * (variant.scale || 1);
  const fw = fh / ratio;

  const handleCreateAccount = () => onCreateAccount?.();

  const handleLogin = () => onLogin?.();

  const rise = (v) => ({
    opacity: v,
    transform: [
      {
        translateY: v.interpolate({
          inputRange: [0, 1],
          outputRange: [ENTER_OFFSET, 0],
        }),
      },
    ],
  });

  return (
    <View style={styles.root}>
      <StatusBar barStyle="light-content" backgroundColor={COLORS.brand} />

      <Grid width={width} height={height} />

      <SafeAreaView style={styles.safeArea}>
        {/* MARQUE */}
        <Animated.View style={[styles.header, { opacity: enter[0] }]}>
          <Image
            source={
              LOGO_VARIANT === "horizontal" ? LOGO_HORIZONTAL : LOGO_SYMBOL
            }
            accessibilityRole="image"
            accessibilityLabel="Pro’Mètre"
            resizeMode="contain"
            style={LOGO_VARIANT === "horizontal" ? styles.logoWide : styles.logo}
          />
        </Animated.View>

        {/* DESSIN (décoratif, se joue tout seul) */}
        <Animated.View
          accessible={false}
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
          {...pan.panHandlers}
          style={[
            styles.drawingZone,
            { opacity: exit, transform: [{ translateX: drag }] },
          ]}
        >
          <CotedDrawing
            variant={variant}
            fw={fw}
            fh={fh}
            progress={progress}
          />
        </Animated.View>

        <Dots count={VARIANTS.length} active={index} onSelect={goTo} />

        {/* TEXTE + ACTIONS */}
        <View style={styles.bottom}>
          <Animated.View style={[styles.fullWidth, rise(enter[1])]}>
            <Text
              accessibilityRole="header"
              numberOfLines={1}
              adjustsFontSizeToFit
              minimumFontScale={0.85}
              maxFontSizeMultiplier={1.2}
              style={styles.title}
            >
              Bienvenue sur Pro’Mètre
            </Text>
          </Animated.View>

          <Animated.View style={rise(enter[2])}>
            <Text maxFontSizeMultiplier={1.3} style={styles.subtitle}>
              Simplifiez vos relevés et gagnez du temps sur chaque chantier.
            </Text>
          </Animated.View>

          <Animated.View style={[styles.fullWidth, rise(enter[3])]}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Créer un compte"
              onPress={handleCreateAccount}
              android_ripple={{ color: "rgba(0,50,58,0.12)" }}
              style={({ pressed }) => [
                styles.createButton,
                pressed && styles.createButtonPressed,
              ]}
            >
              <Text maxFontSizeMultiplier={1.3} style={styles.createText}>
                Créer un compte
              </Text>
            </Pressable>
          </Animated.View>

          <Animated.View style={rise(enter[4])}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel="Vous avez déjà un compte ? Se connecter"
              onPress={handleLogin}
              hitSlop={8}
              style={({ pressed }) => [
                styles.loginButton,
                pressed && styles.loginPressed,
              ]}
            >
              <Text maxFontSizeMultiplier={1.3} style={styles.loginText}>
                Vous avez déjà un compte ?{" "}
                <Text style={styles.loginBold}>Se connecter</Text>
              </Text>
            </Pressable>
          </Animated.View>
        </View>
      </SafeAreaView>
    </View>
  );
}

export default WelcomeScreen;

